<script setup>
import {ref,onMounted} from 'vue'
import {request} from './client'
import './student-count.css'
const config=ref(null),data=ref(null),site=ref(''),status=ref('Pending'),month=ref(''),page=ref(0),busy=ref(false),error=ref(''),notice=ref(''),selected=ref(null),note=ref('')
const form=ref({unit_lkr:5,month:'',enabled:true,bank:{bank_name:'',account_name:'',account_number:'',branch:''},reason:''})
const money=n=>new Intl.NumberFormat('en-LK',{style:'currency',currency:'LKR'}).format((n||0)/100)
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){if(site.value)data.value=await request('student_count_admin','bills',{site:site.value,month:month.value,status:status.value,page:page.value},'GET')}
async function settings(){config.value=await request('student_count_admin','settings',{},'GET');const active=config.value.rates.at(-1);form.value={unit_lkr:(active?.unit_minor??500)/100,month:active?.month>config.value.current_month?active.month:config.value.current_month,enabled:active?.enabled??true,bank:config.value.bank,reason:''};site.value=site.value||config.value.sites[0]||'';await load()}
async function save(){await run(async()=>{await request('student_count_admin','configure',{...form.value,enabled:form.value.enabled?1:0,revision:config.value.revision});await settings();notice.value='Student-count settings saved. Existing bills are unchanged.'})}
async function review(decision){await run(async()=>{await request('student_count_admin','review',{site:site.value,invoice:selected.value.name,decision,note:note.value,modified:selected.value.modified});selected.value=null;await load();notice.value=decision==='Paid'?'Payment approved.':'Submission rejected. The provider can upload a new receipt.'})}
const proof=row=>'/api/method/institute_lms.student_count_admin.proof?'+new URLSearchParams({site:site.value,invoice:row.name})
onMounted(()=>run(settings))
</script>
<template><section class="student-count-space"><p v-if="error" role="alert" class="count-error">{{error}}</p><p v-if="notice" role="status" class="count-notice">{{notice}}</p><form v-if="config" class="count-admin-settings" @submit.prevent="save"><h2>Monthly student-count pricing</h2><p>One charge per student, per institute or independent teacher, after two distinct attended sessions in a calendar month.</p><div class="count-form-grid"><label>Rate per student (LKR)<input v-model="form.unit_lkr" type="number" min="0" max="100000" step="0.01" required></label><label>Effective month<input v-model="form.month" type="month" :min="config.current_month" required><small>Existing monthly rates are fixed. Schedule price changes for next month.</small></label></div><label class="count-check"><input v-model="form.enabled" type="checkbox"> Enable student-count billing from this month</label><h3>Receiving bank account</h3><div class="count-form-grid"><label>Account holder<input v-model="form.bank.account_name" maxlength="140" required></label><label>Account number<input v-model="form.bank.account_number" maxlength="140" required></label><label>Bank<input v-model="form.bank.bank_name" maxlength="140" required></label><label>Branch<input v-model="form.bank.branch" maxlength="140" required></label></div><label>Change reason<input v-model="form.reason" minlength="10" maxlength="1000" required placeholder="Explain the rate or bank-details change"></label><button class="button primary" :disabled="busy">Save settings</button></form>
<section class="count-admin-review"><h2>Student-count payments</h2><p>Check your bank account and the uploaded receipt before approving a payment.</p><form class="count-filters" @submit.prevent="page=0;run(load)"><label>Campus<select v-model="site" required><option v-for="s in config?.sites||[]" :key="s">{{s}}</option></select></label><label>Month<input v-model="month" type="month"></label><label>Status<select v-model="status"><option value="">All statuses</option><option>Pending</option><option>Unpaid</option><option>Paid</option><option>Rejected</option></select></label><button class="button subtle" :disabled="busy">Refresh payments</button></form>
<div v-if="data?.rows.length" class="count-table"><table><thead><tr><th>Provider / month</th><th>Student count</th><th>Total</th><th>Status</th><th>Receipt & review</th></tr></thead><tbody><tr v-for="r in data.rows" :key="r.name"><td><strong>{{r.provider_name}}</strong><small>{{r.provider_role}} · {{r.month}}</small></td><td>{{r.quantity}} × {{money(r.unit_minor)}}</td><td><strong>{{money(r.amount_minor)}}</strong></td><td><span class="count-status" :class="r.status.toLowerCase()">{{r.status}}</span><small>{{r.review_note}}</small></td><td><a v-if="r.proof_file" :href="proof(r)" class="text-button">Download receipt</a><button v-if="r.status==='Pending'" class="button subtle" :disabled="busy" @click="selected=r;note=''">Review payment</button><small>{{r.reference}}</small></td></tr></tbody></table></div><div v-else-if="data" class="count-empty"><h3>No matching payments</h3><p>Provider submissions appear here when they upload a receipt for a completed month.</p></div><nav class="count-actions" v-if="page||data?.has_next"><button class="button subtle" :disabled="busy||!page" @click="page--;run(load)">Previous</button><button class="button subtle" :disabled="busy||!data?.has_next" @click="page++;run(load)">Next</button></nav>
<form v-if="selected" class="count-receipt-form" @submit.prevent="review('Paid')"><h3>Review {{selected.provider_name}}</h3><p>{{selected.month}} · {{selected.quantity}} students · {{money(selected.amount_minor)}}</p><p>Transfer reference: <strong>{{selected.reference}}</strong></p><label>Bank confirmation / rejection reason<textarea v-model="note" minlength="10" maxlength="1000" required></textarea></label><div class="count-actions"><button class="button primary" :disabled="busy||note.trim().length<10">Approve payment</button><button type="button" class="button subtle" :disabled="busy||note.trim().length<10" @click="review('Rejected')">Reject receipt</button><button type="button" class="text-button" :disabled="busy" @click="selected=null">Cancel</button></div></form></section></section></template>
